<?php

declare(strict_types=1);

use Polyspec\Template\Loader\ArrayLoader;

function generatedArtifactLoader(string $root): ArrayLoader
{
    $all = json_decode(base64_decode('', true), true, 512, JSON_THROW_ON_ERROR);
    $id = basename($root);
    if (!isset($all[$id])) throw new RuntimeException('generated templates are missing for ' . $id);
    $templates = [];
    foreach ($all[$id] as $name => $encoded) $templates[$name] = json_decode(hex2bin($encoded), true, 512, JSON_THROW_ON_ERROR);
    return new ArrayLoader($templates);
}
